import statistics
from common import *
TITLE={
'version_note':'SHA условия + заметка Qwen','blind_note':'Слепое расписание + заметка Qwen',
'uncertainty_note':'Неоднозначность по Qwen','hybrid_note':'SHA и неоднозначность, квоты 3:1',
'version_raw':'SHA условия + первые 40 токенов','blind_raw':'Слепое расписание + первые 40 токенов',
'never_note':'Заметка Qwen без чтения','never_raw':'Первые 40 токенов без чтения','always_current':'Каждый раз текущий текст'}
ORDER=list(TITLE)
def n(v):return str(v).replace('.',',')
def fmt(x):return ('+' if x>0 else '')+n(f'{x:.2f}')
def num(x):return f'{x:,}'.replace(',',' ')
def contrast_text(s):
    return f"{fmt(s['delta_pp'])} п.п., 95% стратифицированный бутстреп-интервал [{fmt(s['lower_pp'])}, {fmt(s['upper_pp'])}], выигрыши/потери {s['wins']}/{s['losses']}, точный двусторонний p = {n(format(s['p'],'.4f'))}"
def main():
    res=read('results.json');nat=read('native_costs.json'); v=read('verification.json'); aa=res['author'];ee=res['enhanced']
    text=['# Когда кодовому агенту стоит перечитывать условие','']
    for co,nm in [('primary','На основной выборке'),('replication','На отложенной выборке')]:
        s=aa[co];a=s['policy']['version_note'];b=s['policy']['blind_note']
        text.append(f"**{nm}** маршрутизация по хешу решила {a['solve']} из {s['n']} задач, слепой контроль — {b['solve']} из {s['n']}. Число повторных чтений в каждом условии равнялось {a['rereads']}. Парная разница {contrast_text(s['contrast']['version_note-vs-blind_note'])}.")
        text.append('')
    text+=['Google Research опубликовала исходную и вручную проверенную редакции одних и тех же задач MBPP. Исходное описание физически читалось до сброса контекста. Новое условие поступало в запрос Qwen только при перечитывании. В текстах изданий встречаются изменения требований, уточнения и редакторская правка. На каждом этапе модель видела неизменный публичный интерфейс. Референсные тела, списки тестов, ожидаемые ответы и обратная связь от оценщика в её промпты не входили. Примеры внутри авторской прозы сохранялись. [Корпус и авторский протокол](https://github.com/google-research/google-research/tree/f82046ba5aabbbb427dbfd38a254d26bff08b533/mbpp), [статья MBPP](https://arxiv.org/abs/2108.07732).','',
    'Из 257 проверенных задач тестовой части условия отбора прошла 221, включая 101 изменённое описание и 120 неизменённых. После заранее указанного хеширования выделено 64 задачи в основную и 32 в отдельную проверочную выборку. Оба среза содержат поровну изменений и совпадений. Из состава исключены 16 задач, описания которых просматривались при проверке структуры данных. Для каждой задачи была одна детерминированная генерация каждого отличающегося запроса. Репликация разделена по заданиям и использует тот же корпус, модель и процедуру.','',
    'Перед сбросом Qwen формировала заметку и оценивала неоднозначность исходной заявки по шкале 0–100. Максимум памяти составлял 40 токенов текста плюс сигнатура. Сравнение байтовых SHA-256 использует отдельный индекс текущих ревизий. В память метода входит и прежний 32-байтный SHA. Для слепого расписания SHA истории не нужен. Роутер распределяет перечитывания, после чего декодер получает либо актуальное полное описание, либо один из двух вариантов памяти. Выбор по неоднозначности использует упорядоченный пакет заданий, гибрид выдаёт три четверти своих чтений изменённым описаниям, остальные неизменённым. Внутри каждой группы он берёт наивысшую оценку неоднозначности.','',
    '## Авторские тесты MBPP','',
    '| Политика | Решено, 64 | Чтения | Вход / выход, токены | Решено, 32 | Чтения | Вход / выход, токены |',
    '|---|---:|---:|---:|---:|---:|---:|']
    for pol in ORDER:
        a=aa['primary']['policy'][pol];b=aa['replication']['policy'][pol]
        text.append(f"| {TITLE[pol]} | {a['solve']} | {a['rereads']} | {num(a['prompt_tokens'])} / {num(a['completion_tokens'])} | {b['solve']} | {b['rereads']} | {num(b['prompt_tokens'])} / {num(b['completion_tokens'])} |")
    text+=['','Текстовая заметка и одинаковая длина памяти не гарантируют, что сохранились возвращаемый тип, правило округления или деталь обработки границы. Чтобы отделить уточнения издателя от потерь при записи заметки, каждая задача была действительно решена как по текущему документу, так и по обеим формам старой памяти. Таблица ниже показывает, сколько раз текущее описание изменило исход относительно заметки Qwen.','',
        '| Выборка | Состояние описания | Задач | Перечитывание помогло | Перечитывание повредило | Оба исхода одинаковы |','|---|---|---:|---:|---:|---:|']
    for co,title in [('primary','Основная'),('replication','Проверочная')]:
        for g,label in [('True','Изменено издателем'),('False','Совпадает побайтно')]:
            z=aa[co]['by_version'][g]['read_vs_note']
            text.append(f"| {title} | {label} | {z['n']} | {z['wins']} | {z['losses']} | {z['ties']} |")
    text+=['']
    for co,lab in [('primary','основных'),('replication','проверочных')]:
        z=aa[co];f=z['policy']['version_note']['solve'];exp=z['expected_blind_solves'];costs=z['policy']['version_note'];raw=z['policy']['version_raw']
        text.append(f"На {z['n']} {lab} задачах среднее по всем равновероятным распределениям половины чтений составляет {n(exp)} решённых задач, отбор по изменению с заметкой решает {f}. Дословные первые 40 токенов совпали со всем текущим текстом в {z['unchanged_raw_equals_current']} случаях. Вариант с дословной памятью и тем же отбором решил {raw['solve']} задач, его разность с вариантом с заметкой приведена в results.json. Чтение по SHA с заметкой передало {num(costs['reread_bytes'])} байт актуального текста. Для построения индекса хешей провайдер просмотрел {num(costs['sha_provider_current_bytes'])} байт текущих условий.")
        text.append('')
    text+=['## Усиленные тесты MBPP+','',
           'После фиксации основного дизайна, до открытия каких-либо баллов, зарегистрировано испытание тех же физических программ на неизменённой исполняемой программе тестирования из MBPP+ v0.2.0 OriginFmt. Отбор определялся наличием ID и совпадающей точки входа. Условия задания в промпте по-прежнему принадлежали Google MBPP. В усиленной редакции отдельно учтены собственный исправленный эталон и совместимость оригинального эталона Google. [Релиз MBPP+](https://github.com/evalplus/mbppplus_release/releases/tag/v0.2.0).','',
           '| Политика | Основная, '+str(ee['primary']['n'])+' | Проверочная, '+str(ee['replication']['n'])+' |','|---|---:|---:|']
    for pol in ORDER:text.append(f"| {TITLE[pol]} | {ee['primary']['policy'][pol]['solve']} | {ee['replication']['policy'][pol]['solve']} |")
    text.append('')
    for co,lab in [('primary','Основная'),('replication','Проверочная')]:
        z=ee[co];occ=z['statuses']
        coverage=z['n'];va=z['valid']['version_note'];vb=z['valid']['blind_note']
        text.append(f"{lab} выборка MBPP+ включает {coverage} заданий. SHA против слепого расписания даёт {contrast_text(z['contrast']['version_note-vs-blind_note'])}. Усиленный эталон прошёл {occ['plus_reference'].get('pass',0)} из {coverage}, эталон Google — {occ['reference'].get('pass',0)}, заведомо неисправная заглушка — {occ['stub'].get('pass',0)}. На срезе с прошедшим эталоном MBPP+ и провалившейся заглушкой два способа решили {va['solve']} и {vb['solve']} из {va['n']}.")
        text.append('')
    for co,title in [('primary','Основная'),('replication','Проверочная')]:
        z=aa[co];sf=read('scores.json');sp=read('plus_scores.json'); ids=ee[co]['coverage_ids']
        policies=read('allocations.json')[co];changes={}
        for pol in ['version_note','blind_note','version_raw','always_current']:
            lost=[];gained=[]
            for i in ids:
                br=policies[pol][str(i)];old=sf[str(i)][br]['status']=='pass';new=sp[str(i)][br]['status']=='pass'
                if old and not new:lost.append(i)
                if new and not old:gained.append(i)
            changes[pol]=(len(lost),len(gained))
        text.append(f"{title} выборка при смене набора тестов. Среди пересекающихся ID для SHA с заметкой {changes['version_note'][0]} программ прошли Google и провалили MBPP+, в противоположную сторону изменились {changes['version_note'][1]}. Для полного текущего описания соответственно {changes['always_current'][0]} и {changes['always_current'][1]}. Расписание осталось заданным по всей исходной выборке, поэтому у отдельных политик на пересечении число чтений может отличаться.")
        text.append('')
    text+=['## Расходы и проверяемость','']
    for co,lab in [('primary','основной'),('replication','проверочной')]:
        z=aa[co];p=z['policy'];s=z['statuses'];invalid_notes=z['n']-z['complete_note_pairs']
        text.append(f"На {lab} выборке положительный контроль Google прошёл {s['reference'].get('pass',0)} из {z['n']}, отрицательный — {s['stub'].get('pass',0)}. Повреждённых JSON-заметок с подстановкой исходного текста — {invalid_notes}. Медиана размера заметки Qwen {n(statistics.median(z['note_tokens']))} токенов, дословной записи — {n(statistics.median(z['raw_tokens']))}. Суммарное время запросов при раздельном исполнении политик по сохранённым временам отклика составляет {n(round(p['version_note']['seconds'],1))} с для SHA с заметкой, {n(round(p['version_raw']['seconds'],1))} с для SHA с дословной записью и {n(round(p['always_current']['seconds'],1))} с для полного текущего текста.")
        text.append('')
    text += [f"За две когорты выполнено {nat['unique_calls']} различных нативных вызовов Qwen3.8-27B UD-Q4_K_M на NVIDIA RTX 3090 из {v['writer_and_reader_logical_calls']} запросов фаз записи и чтения с учётом повторов. Фактически обработано {num(nat['prompt_tokens'])} входных и {num(nat['completion_tokens'])} выходных токенов за {n(round(nat['seconds'],1))} с суммарного времени HTTP-запросов. Параллелизм сервера 1, температура 0, seed 18112026, для каждого варианта программы максимум 416 выходных токенов. Решающие политики воспроизводятся офлайн из действительно сгенерированных ветвей. Девять политик не означают девять независимых серий генерации.",'',
    'У двух политик первичного сравнения одинаковы модель, число записей и решений, верхние пределы токенов и число чтений. Переданная длина условий и фактически израсходованные токены различаются. Время включает вызов писателя для политик с заметкой; копирование дословного текста не требует LLM. Отдельные байты и токены посчитаны в results.json и item_results.csv. Для выбора по SHA нужен доступ к версии каждого источника. При вынужденном хешировании всех документов экономия касается текста, отправляемого модели; при наличии индекса объекта в VCS его формирование может быть общей инфраструктурной операцией.','',
    'Размер эффекта относится к коротким англоязычным заявкам из одного публичного корпуса, где модель могла ранее видеть задачу. В опыте не измерялись долговременные изменения репозитория, самостоятельное обнаружение изменённых файлов, сохранение плана многошагового исправления, другие модели или вариация по seed. На дополнительные проверки действовал предел 5 с и 192 МиБ на процесс; все диагностические коды, ограничения синтаксиса и таймауты доступны в файлах оценок. Перепроверка хешей, исходных промптов, декодированных программ и присоединения результатов выполняется командой из REPRODUCE.md.']
    text+=['','## Что влияет на численную разницу','',
      'У всех 96 заданий исходный текст занимал от 8 до 39 токенов и целиком помещался в предел 40. На 94 заданиях модель записала заметку длиннее оригинала. Копирование исходного текста вместе с SHA воспроизвело все запросы полного чтения и сэкономило ровно половину повторных загрузок. Число входных и выходных токенов решателя в этих двух условиях совпадает до единицы. На 63 из 96 исходных заявок Qwen присвоила неоднозначности одну и ту же оценку 15 из 100; порядок разрешения совпадений влиял на распределение чтений.','',
      'В основной выборке преимущество маршрутизации по SHA над заранее выбранным слепым расписанием равно нулю. На отложенных заданиях есть пять парных выигрышей, три на действительно изменённых описаниях и два на неизменённых. В четырёх из пяти случаев проигравшая ветвь достигла лимита 416 выходных токенов и дала синтаксически незавершённый файл. Такие исходы объясняются в том числе взаимодействием формулировки и бюджета генерации. При пяти дискордантных парах точный двусторонний тест даёт 0,0625; положительная нижняя граница обычного бутстрепа по задачам чувствительна к отсутствию наблюдавшихся проигрышей.','',
      'Ограниченный исполнитель заблокировал два исходных эталона в основной когорте. В задаче 264 встречался вызов exit, в задаче 307 — импорт deepcopy. На срезе остальных 62 задач разница SHA+заметка и слепого расписания составила 0 п.п. Все 83 усиленных эталона EvalPlus прошли. На MBPP+ исключение задач с таймаутом любой ветви или контроля оставило 54 основных задания и все 26 проверочных; выводы главного сравнения при этом сохранились.']
    if (ROOT/'replay.json').exists():
        rp=read('replay.json')
        if all(r['all_equal'] for r in rp.values()):
            text+=['',f"При полном повторном исполнении совпали все {rp['author']['physical_outcome_rows']} строк статусов MBPP и все {rp['enhanced']['physical_outcome_rows']} строк MBPP+, включая положительные и отрицательные контроли. В пределах одного задания байтово одинаковые программы тестировались один раз."]
    if (ROOT/'diagnostics.json').exists():
        dd=read('diagnostics.json');g=dd['gpu_sampling']
        text+=['',f"По собственному журналу сервер был готов принимать запросы через 17,33 с после запуска. Это время вынесено из длительности генераций. В {g['observations']} аппаратных замерах на основной генерации максимальное наблюдавшееся использование видеопамяти всей видеокарты достигло {num(g['peak_vram_mib'])} МиБ. Программные и модельные SHA-256 находятся в runtime/confirmed_binaries.json."]
    if (ROOT/'cap1024/summary_ru.md').exists():
        text+=['',(ROOT/'cap1024/summary_ru.md').read_text(encoding='utf8').strip()]
    (ROOT/'summary_ru.md').write_text('\n'.join(text)+'\n',encoding='utf8')
if __name__=='__main__':main()

